int licznik = 0;
int liczba = 0;
int minimum, maksimum, jasnosc;

void Znak(int iNumer) {
  // Sterowanie pinem 8 (odpowiada ostatniemu elementowi w liście Pythona: index 6)
  digitalWrite(8, ((iNumer == 0) || (iNumer == 1) || (iNumer == 7)) ? HIGH : LOW);

  // Sterowanie segmentami podłączonymi do PORTD (piny od D2 do D7)
  // Kolejność bitów w 0b[D7][D6][D5][D4][D3][D2][TX][RX]
  switch (iNumer) {
    case 0: PORTD = 0b00000000; break; // [0,0,0,0,0,0] dla D2-D7
    case 1: PORTD = 0b11100100; break; // [1,0,0,1,1,1] -> D7,D6,D5=1, D2=1
    case 2: PORTD = 0b10010000; break; // [0,0,1,0,0,1] -> D7=1, D4=1
    case 3: PORTD = 0b11000000; break; // [0,0,0,0,1,1] -> D7=1, D6=1
    case 4: PORTD = 0b01100100; break; // [1,0,0,1,1,0] -> D6,D5=1, D2=1
    case 5: PORTD = 0b01001000; break; // [0,1,0,0,1,0] -> D6=1, D3=1
    case 6: PORTD = 0b00001000; break; // [0,1,0,0,0,0] -> D3=1
    case 7: PORTD = 0b11100000; break; // [0,0,0,1,1,1] -> D7,D6,D5=1
    case 8: PORTD = 0b00000000; break; // [0,0,0,0,0,0] -> wszystkie 0
    case 9: PORTD = 0b01000000; break; // [0,0,0,0,1,0] -> D6=1
    default: PORTD = 0b00000000; break;
  }
}

void setup() {
  // Ustawienie pinów od D2 do D8 jako wyjścia
  for (int i = 2; i < 9; i++) {
    pinMode(i, OUTPUT);
  }
  pinMode(10, OUTPUT);
  pinMode(11, OUTPUT);

  delay(1000);
  minimum = analogRead(0);
  maksimum = minimum;
}

void loop() {
  // Multipleksowanie wyświetlacza dwucyfrowego (cyfra jedności)
  digitalWrite(11, LOW);
  Znak(liczba % 10);
  digitalWrite(10, HIGH);
  delay(2);

  // Multipleksowanie wyświetlacza dwucyfrowego (cyfra dziesiątek)
  digitalWrite(10, LOW);
  Znak((liczba / 10) % 10);
  digitalWrite(11, HIGH);
  delay(2);

  // Co pewien czas odczytaj wartość z analog(0) i przeskaluj ją do zakresu 0-99
  if (licznik++ > 100) {
    jasnosc = analogRead(0);

    if (minimum > jasnosc) minimum = jasnosc;
    if (maksimum < jasnosc) maksimum = jasnosc;

    // Zabezpieczenie przed dzieleniem przez zero
    if (minimum != maksimum) {
      jasnosc = 99 * (jasnosc - minimum) / (maksimum - minimum);
    } else {
      jasnosc = 0;
    }

    liczba = jasnosc;
    licznik = 0;
  }
}
